export function CtaSection({
  heading = "{{heading}}",
  body = "{{body}}",
  buttonText = "{{buttonText}}",
  bg = "{{bg}}",
  align = "{{align}}",
}) {
  return (
    <section style={{ padding: "56px 24px", borderRadius: 16, font: "16px/1.5 system-ui, sans-serif", color: "#FAF7F2", background: bg, textAlign: align }}>
      <h2 style={{ margin: "0 0 12px", fontSize: 30, fontWeight: 800 }}>{heading}</h2>
      <p style={{ margin: align === "center" ? "0 auto 24px" : "0 0 24px", opacity: 0.85, maxWidth: "52ch" }}>{body}</p>
      <button type="button" style={{ background: "#FAF7F2", border: "none", padding: "14px 28px", borderRadius: 10,
        fontWeight: 700, fontSize: 15, cursor: "pointer", color: bg }}>
        {buttonText}
      </button>
    </section>
  );
}
